-- Platform content is separate from lecturer public_lessons. Writes only pass
-- through an admin RPC; published activity revisions are never overwritten.
create table public.platform_catalog (
  id text primary key check (id = 'hanzi-platform'),
  revision bigint not null check (revision > 0),
  data jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id)
);
alter table public.platform_catalog enable row level security;
revoke all on public.platform_catalog from public, anon, authenticated;
grant select on public.platform_catalog to authenticated;
create policy platform_catalog_read on public.platform_catalog for select to authenticated
using (private.current_app_role() is not null);

create function private.content_assert(ok boolean, message text) returns void
language plpgsql set search_path = '' as $$ begin
  if ok is distinct from true then raise exception '%', message using errcode = '22023'; end if;
end; $$;
create function private.content_text(value jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select jsonb_typeof(value) = 'string' and char_length(btrim(value #>> '{}')) between 1 and 50000;
$$;
create function private.content_strings(value jsonb, minimum integer default 0) returns boolean
language plpgsql immutable set search_path = '' as $$ begin
  if jsonb_typeof(value) is distinct from 'array' then return false; end if;
  return jsonb_array_length(value) >= minimum and not exists (select 1 from jsonb_array_elements(value) s where not coalesce(private.content_text(s), false));
end; $$;
create function private.content_has_id(items jsonb, target text) returns boolean
language sql immutable set search_path = '' as $$ select exists (select 1 from jsonb_array_elements(items) i where i->>'id'=target); $$;
create function private.content_refs(refs jsonb, items jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$ begin
  if not coalesce(private.content_strings(refs),false) then return false; end if;
  return not exists (select 1 from jsonb_array_elements_text(refs) r where not private.content_has_id(items,r))
    and (select count(*)=count(distinct r) from jsonb_array_elements_text(refs) r);
end; $$;
create function private.content_examples(items jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$ begin
  if jsonb_typeof(items) is distinct from 'array' then return false; end if;
  return not exists (select 1 from jsonb_array_elements(items) i where jsonb_typeof(i) is distinct from 'object'
    or not coalesce(private.content_text(i->'hanzi') and private.content_text(i->'pinyin') and private.content_text(i->'meaning'),false));
end; $$;
create function private.content_current(items jsonb) returns jsonb
language sql immutable set search_path = '' as $$
  select coalesce(jsonb_agg(v),'[]') from (select distinct on (i->>'id') i as v from jsonb_array_elements(items) i order by i->>'id',(i->>'revision')::integer desc) q;
$$;
create function private.validate_platform_catalog(pack jsonb) returns void
language plpgsql set search_path = '' as $$
declare bucket text; item jsonb; q jsonb; opt jsonb; accepted jsonb; ref text; current_items jsonb; categories jsonb; levels jsonb;
begin
  perform private.content_assert(jsonb_typeof(pack)='object' and pack->>'id'='hanzi-platform' and pack->'schemaVersion'='1'::jsonb, 'Unsupported platform content schema.');
  categories := pack->'taxonomy'->'categories'; levels := pack->'taxonomy'->'languageLevels';
  for bucket in select unnest(array['activities','grammarTopics','vocabulary','sentences']) loop
    perform private.content_assert(jsonb_typeof(pack->bucket)='array' and jsonb_array_length(pack->bucket)<=5000,'Content collections must be arrays of at most 5000 entries.');
    for item in select value from jsonb_array_elements(pack->bucket) loop
      perform private.content_assert(jsonb_typeof(item)='object' and jsonb_typeof(item->'id')='string' and (item->>'id') ~ '^[a-z0-9][a-z0-9:_-]{0,159}$','Choose a stable content identifier.');
      perform private.content_assert(private.content_has_id(levels,item->>'languageLevel') and private.content_has_id(pack->'taxonomy'->'difficulties',item->>'difficulty'),'Choose a supported language level and difficulty.');
      perform private.content_assert(not (item ? 'archived') or jsonb_typeof(item->'archived')='boolean','Invalid archive flag.');
    end loop;
    if bucket <> 'activities' then
      perform private.content_assert((select count(*)=count(distinct i->>'id') from jsonb_array_elements(pack->bucket) i),'Content identifiers must be unique.');
    end if;
  end loop;
  for item in select value from jsonb_array_elements(pack->'vocabulary') loop
    perform private.content_assert(private.content_examples(jsonb_build_array(item)) and jsonb_typeof(item->'categoryId')='string' and private.content_has_id(categories,item->>'categoryId') and item->>'categoryId'<>'all','Complete the word, pinyin, meaning and topic.');
    perform private.content_assert(jsonb_typeof(item->'sourceId')='string' and private.content_has_id(pack->'taxonomy'->'sources',item->>'sourceId'),'Choose a known vocabulary source.');
    perform private.content_assert(item->'level'='null'::jsonb or (jsonb_typeof(item->'level')='number' and item->>'level' ~ '^[1-6]$'),'HSK level must be empty or an integer from 1 to 6.');
    foreach ref in array array['traditional','partOfSpeech','sourceEntryId'] loop
      perform private.content_assert(not (item ? ref) or private.content_text(item->ref),'Optional vocabulary fields must not be blank.');
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(pack->'grammarTopics') loop
    perform private.content_assert(private.content_text(item->'title') and private.content_text(item->'explanation') and private.content_examples(item->'examples'),'Complete the grammar title, explanation and examples.');
    perform private.content_assert(private.content_refs(item->'prerequisites',pack->'grammarTopics'),'Grammar prerequisites must refer to existing topics without duplicates.');
    perform private.content_assert(not (item ? 'vocabularyIds') or private.content_refs(item->'vocabularyIds',pack->'vocabulary'),'Grammar vocabulary links must refer to existing words.');
  end loop;
  for item in select value from jsonb_array_elements(pack->'activities') loop
    perform private.content_assert(item->>'source'='platform' and item->>'kind' in ('lesson','exercise') and item->>'publication' in ('published','archived'),'Invalid platform content type or publication.');
    perform private.content_assert(jsonb_typeof(item->'revision')='number' and item->>'revision' ~ '^[1-9][0-9]*$','Activity revisions must be positive integers.');
    perform private.content_assert(private.content_text(item->'title') and char_length(item->>'title')<=160 and private.content_text(item->'description'),'Complete the title and description.');
    perform private.content_assert(jsonb_typeof(item->'minutes')='number' and (item->>'minutes')::numeric>0 and (item->>'minutes')::numeric<=240,'Duration must be between 1 and 240 minutes.');
    perform private.content_assert(private.content_has_id(categories,item->>'category') and private.content_has_id(pack->'taxonomy'->'courseLines',item->>'line'),'Choose a valid topic and course line.');
    perform private.content_assert(jsonb_typeof(item->'position'->'x')='number' and jsonb_typeof(item->'position'->'y')='number' and (item->'position'->>'x')::numeric>=0 and (item->'position'->>'y')::numeric>=0,'Map coordinates must be non-negative numbers.');
    perform private.content_assert(private.content_strings(item->'objectives',1) and private.content_strings(item->'explanation',1) and private.content_examples(item->'examples'),'Add objectives, explanation paragraphs and complete examples.');
    perform private.content_assert(private.content_refs(item->'vocabularyIds',pack->'vocabulary') and private.content_refs(item->'grammarTopicIds',pack->'grammarTopics'),'Activity vocabulary and grammar links must exist.');
    perform private.content_assert(private.content_strings(item->'features') and not exists(select 1 from jsonb_array_elements_text(item->'features') f where f<>'tone-guide'),'Unknown teaching feature.');
    perform private.content_assert((select count(*)=count(distinct f) from jsonb_array_elements_text(item->'features') f),'Teaching features cannot be duplicated.');
    perform private.content_assert(jsonb_typeof(item->'questions')='array' and jsonb_array_length(item->'questions') between 1 and 100,'Add between 1 and 100 questions.');
    perform private.content_assert((select count(*)=count(distinct v->>'id') from jsonb_array_elements(item->'questions') v),'Question identifiers must be unique within an activity.');
    for q in select value from jsonb_array_elements(item->'questions') loop
      perform private.content_assert(jsonb_typeof(q->'id')='string' and (q->>'id') ~ '^[a-z0-9][a-z0-9:_-]{0,159}$' and private.content_text(q->'prompt') and private.content_text(q->'explanation'),'Complete each question identifier, prompt and feedback explanation.');
      foreach ref in array array['hint','audioText'] loop
        perform private.content_assert(not(q ? ref) or private.content_text(q->ref),'Optional hint and audio text must not be blank.');
      end loop;
      if q->>'type'='choice' then
        perform private.content_assert(jsonb_typeof(q->'options')='array' and jsonb_array_length(q->'options') between 2 and 10,'Choice questions need 2–10 options.');
        perform private.content_assert((select count(*)=count(distinct v->>'id') from jsonb_array_elements(q->'options') v),'Choice option identifiers must be unique.');
        for opt in select value from jsonb_array_elements(q->'options') loop
          perform private.content_assert(jsonb_typeof(opt->'id')='string' and (opt->>'id') ~ '^[a-z0-9][a-z0-9:_-]{0,159}$' and private.content_text(opt->'text') and (not(opt ? 'pinyin') or private.content_text(opt->'pinyin')),'Complete each answer option.');
        end loop;
        perform private.content_assert(jsonb_typeof(q->'answer')='string' and private.content_has_id(q->'options',q->>'answer'),'Select a correct answer from the options.');
      elsif q->>'type'='order' then
        perform private.content_assert(private.content_strings(q->'tokens',1) and jsonb_typeof(q->'acceptedOrders')='array' and jsonb_array_length(q->'acceptedOrders')>0,'Ordering questions need tokens and an accepted order.');
        for accepted in select value from jsonb_array_elements(q->'acceptedOrders') loop
          perform private.content_assert(private.content_strings(accepted,1),'Accepted orders need text tokens.');
          perform private.content_assert((select jsonb_agg(v order by v) from jsonb_array_elements(accepted) v)=(select jsonb_agg(v order by v) from jsonb_array_elements(q->'tokens') v),'Every accepted order must use all token occurrences exactly once.');
        end loop;
      else perform private.content_assert(false,'Supported question types are choice and order.'); end if;
    end loop;
    if item ? 'fact' then
      perform private.content_assert(private.content_text(item->'fact'->'title') and private.content_text(item->'fact'->'text') and private.content_text(item->'fact'->'sourceLabel') and (item->'fact'->>'sourceUrl') ~ '^https://','Complete the culture note and an HTTPS source link.');
    end if;
  end loop;
  perform private.content_assert((select count(*)=count(distinct (i->>'id',i->>'revision')) from jsonb_array_elements(pack->'activities') i),'Activity revisions must be unique.');
  perform private.content_assert(not exists(select 1 from jsonb_array_elements(pack->'activities') i group by i->>'id' having count(distinct i->>'kind')>1),'Activities cannot change type.');
  current_items := private.content_current(pack->'activities');
  for item in select value from jsonb_array_elements(pack->'activities') loop
    perform private.content_assert(exists(select 1 from jsonb_array_elements(pack->'activities') i where i->>'id'=item->>'id' and i->>'revision'='1'),'Historical revision 1 must be retained.');
    perform private.content_assert(private.content_refs(item->'prerequisites',current_items),'Activity prerequisites must refer to existing lessons.');
    for ref in select value from jsonb_array_elements_text(item->'prerequisites') loop
      perform private.content_assert(exists(select 1 from jsonb_array_elements(current_items) i where i->>'id'=ref and i->>'kind'='lesson'),'Prerequisites must be lessons.');
      perform private.content_assert((select p.rank<=a.rank from jsonb_array_elements(levels) with ordinality p(v,rank),jsonb_array_elements(levels) with ordinality a(v,rank),jsonb_array_elements(current_items) i where i->>'id'=ref and p.v->>'id'=i->>'languageLevel' and a.v->>'id'=item->>'languageLevel'),'A prerequisite cannot require a higher language level.');
    end loop;
  end loop;
  perform private.content_assert(not exists(
    with recursive walk(node,path,cycle) as (
      select i->>'id',array[i->>'id'],false from jsonb_array_elements(current_items) i
      union all select r,array_append(w.path,r),r=any(w.path) from walk w join lateral jsonb_array_elements(current_items) i on i->>'id'=w.node cross join lateral jsonb_array_elements_text(i->'prerequisites') r where not w.cycle
    ) select 1 from walk where cycle),'Lesson prerequisites contain a cycle.');
  perform private.content_assert(not exists(
    with recursive walk(node,path,cycle) as (
      select i->>'id',array[i->>'id'],false from jsonb_array_elements(pack->'grammarTopics') i
      union all select r,array_append(w.path,r),r=any(w.path) from walk w join lateral jsonb_array_elements(pack->'grammarTopics') i on i->>'id'=w.node cross join lateral jsonb_array_elements_text(i->'prerequisites') r where not w.cycle
    ) select 1 from walk where cycle),'Grammar prerequisites contain a cycle.');
  for item in select value from jsonb_array_elements(pack->'sentences') loop
    perform private.content_assert(private.content_text(item->'meaning') and private.content_text(item->'pinyin') and private.content_strings(item->'tokens',1) and item->>'punctuation' in ('。','？'),'Complete the sentence translation, pinyin, tokens and punctuation.');
    perform private.content_assert(jsonb_typeof(item->'grammarTopicId')='string' and private.content_has_id(pack->'grammarTopics',item->>'grammarTopicId'),'Choose an existing sentence grammar topic.');
    if item ? 'acceptedOrders' then
      perform private.content_assert(jsonb_typeof(item->'acceptedOrders')='array','Accepted sentence orders must be an array.');
      for accepted in select value from jsonb_array_elements(item->'acceptedOrders') loop
        perform private.content_assert(private.content_strings(accepted,1) and (select jsonb_agg(v order by v) from jsonb_array_elements(accepted) v)=(select jsonb_agg(v order by v) from jsonb_array_elements(item->'tokens') v),'Accepted sentence orders must use every token.');
      end loop;
    end if;
    perform private.content_assert(jsonb_typeof(item->'grammarParts')='array','Grammar annotations must be an array.');
    for q in select value from jsonb_array_elements(item->'grammarParts') loop
      perform private.content_assert(private.content_text(q->'label') and private.content_text(q->'text'),'Complete each grammar annotation.');
    end loop;
  end loop;
end; $$;

create function public.get_platform_catalog() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare result jsonb;
begin
  if private.current_app_role() is null then raise exception 'Sign in to read platform content.' using errcode='42501'; end if;
  select jsonb_build_object('revision',revision,'data',data,'updated_at',updated_at) into result from public.platform_catalog where id='hanzi-platform';
  return result;
end; $$;

create function public.admin_save_platform_content(entity_kind text, entity_id text, payload jsonb, expected_revision bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare current_row public.platform_catalog; next_pack jsonb; items jsonb; existing jsonb; new_value jsonb; bucket text; latest jsonb; dependent boolean; new_revision integer;
begin
  if private.current_app_role() is distinct from 'admin' then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  payload := nullif(payload,'null'::jsonb);
  select * into current_row from public.platform_catalog where id='hanzi-platform' for update;
  if private.current_app_role() is distinct from 'admin' then raise exception 'Administrator access is required.' using errcode='42501'; end if;
  if not found or expected_revision is distinct from current_row.revision then raise exception 'Another administrator changed the catalog. Reload before saving.' using errcode='40001'; end if;
  perform private.content_assert(entity_kind in ('lesson','exercise','grammar','vocabulary','sentence') and entity_id ~ '^[a-z0-9][a-z0-9:_-]{0,159}$','Invalid content type or identifier.');
  perform private.content_assert(payload is null or (jsonb_typeof(payload)='object' and octet_length(payload::text)<=150000),'Content must be an object smaller than 150 KB.');
  bucket := case when entity_kind in ('lesson','exercise') then 'activities' when entity_kind='grammar' then 'grammarTopics' when entity_kind='vocabulary' then 'vocabulary' else 'sentences' end;
  next_pack := current_row.data; items := next_pack->bucket; latest := private.content_current(next_pack->'activities');
  if bucket='activities' then
    select i into existing from jsonb_array_elements(latest) i where i->>'id'=entity_id;
    perform private.content_assert(existing is null or existing->>'kind'=entity_kind,'An activity cannot change its type.');
  else select i into existing from jsonb_array_elements(items) i where i->>'id'=entity_id; end if;
  perform private.content_assert(payload is not null or existing is not null,'This item no longer exists.');
  if payload is null then
    dependent := case when entity_kind='lesson' then exists(select 1 from jsonb_array_elements(latest) i where i->>'publication'='published' and i->>'id'<>entity_id and (i->'prerequisites') ? entity_id)
      when entity_kind='grammar' then exists(select 1 from jsonb_array_elements(latest) i where i->>'publication'='published' and (i->'grammarTopicIds') ? entity_id)
        or exists(select 1 from jsonb_array_elements(next_pack->'sentences') i where not coalesce((i->>'archived')::boolean,false) and i->>'grammarTopicId'=entity_id)
        or exists(select 1 from jsonb_array_elements(next_pack->'grammarTopics') i where not coalesce((i->>'archived')::boolean,false) and i->>'id'<>entity_id and (i->'prerequisites') ? entity_id)
      when entity_kind='vocabulary' then exists(select 1 from jsonb_array_elements(latest) i where i->>'publication'='published' and (i->'vocabularyIds') ? entity_id)
        or exists(select 1 from jsonb_array_elements(next_pack->'grammarTopics') i where not coalesce((i->>'archived')::boolean,false) and (i->'vocabularyIds') ? entity_id)
      else false end;
    perform private.content_assert(not dependent,'This item is used by published content. Remove links or archive dependents first.');
  end if;
  if bucket='activities' then
    new_revision := coalesce((existing->>'revision')::integer,0)+1;
    new_value := coalesce(payload,existing)||jsonb_build_object('id',entity_id,'source','platform','kind',entity_kind,'revision',new_revision,'publication',case when payload is null then 'archived' else 'published' end);
    select coalesce(jsonb_agg(case when i->>'id'=entity_id then i||'{"publication":"archived"}'::jsonb else i end),'[]') into items from jsonb_array_elements(items) i;
    items := items||jsonb_build_array(new_value);
  else
    new_value := coalesce(payload,existing)||jsonb_build_object('id',entity_id,'archived',payload is null);
    if entity_kind='vocabulary' and existing is not null then perform private.content_assert(new_value->>'hanzi'=existing->>'hanzi','Published character identities cannot be reassigned. Create a new word.'); end if;
    select coalesce(jsonb_agg(i),'[]') into items from jsonb_array_elements(items) i where i->>'id'<>entity_id;
    items := items||jsonb_build_array(new_value);
  end if;
  next_pack := jsonb_set(next_pack,array[bucket],items);
  if payload is not null then
    if bucket='activities' then
      perform private.content_assert(not exists(select 1 from jsonb_array_elements(next_pack->'vocabulary') i where coalesce((i->>'archived')::boolean,false) and (new_value->'vocabularyIds') ? (i->>'id'))
        and not exists(select 1 from jsonb_array_elements(next_pack->'grammarTopics') i where coalesce((i->>'archived')::boolean,false) and (new_value->'grammarTopicIds') ? (i->>'id'))
        and not exists(select 1 from jsonb_array_elements(latest) i where i->>'publication'='archived' and (new_value->'prerequisites') ? (i->>'id')),'Restore archived references before publishing.');
    elsif bucket='grammarTopics' then
      perform private.content_assert(not exists(select 1 from jsonb_array_elements(next_pack->'vocabulary') i where coalesce((i->>'archived')::boolean,false) and (new_value->'vocabularyIds') ? (i->>'id'))
        and not exists(select 1 from jsonb_array_elements(next_pack->'grammarTopics') i where coalesce((i->>'archived')::boolean,false) and (new_value->'prerequisites') ? (i->>'id')),'Restore archived references before publishing grammar.');
    elsif bucket='sentences' then
      perform private.content_assert(not exists(select 1 from jsonb_array_elements(next_pack->'grammarTopics') i where coalesce((i->>'archived')::boolean,false) and i->>'id'=new_value->>'grammarTopicId'),'Restore the grammar topic before publishing this sentence.');
    end if;
  end if;
  perform private.content_assert(octet_length(next_pack::text)<=5000000,'The catalog exceeds the 5 MB limit.');
  perform private.validate_platform_catalog(next_pack);
  update public.platform_catalog set data=next_pack,revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid() where id='hanzi-platform';
  return public.get_platform_catalog();
end; $$;

revoke all on function private.content_assert(boolean,text),private.content_text(jsonb),private.content_strings(jsonb,integer),private.content_has_id(jsonb,text),private.content_refs(jsonb,jsonb),private.content_examples(jsonb),private.content_current(jsonb),private.validate_platform_catalog(jsonb) from public,anon,authenticated;
revoke all on function public.get_platform_catalog(),public.admin_save_platform_content(text,text,jsonb,bigint) from public,anon;
grant execute on function public.get_platform_catalog(),public.admin_save_platform_content(text,text,jsonb,bigint) to authenticated;

-- The following seed is generated from the checked-in catalog. It preserves
-- all original IDs and answer banks, so no manual data import is required.
insert into public.platform_catalog(id,revision,data) values ('hanzi-platform',1,$hanzi_seed${"schemaVersion":1,"id":"hanzi-platform","taxonomy":{"languageLevels":[{"id":"beginner","label":"Beginner","description":"I am starting from the basics."},{"id":"elementary","label":"Elementary","description":"I know some words and simple phrases."},{"id":"intermediate","label":"Intermediate","description":"I can handle familiar everyday situations."},{"id":"advanced","label":"Advanced","description":"I can use Chinese in a wide range of situations."}],"difficulties":[{"id":"gentle","label":"Gentle","description":"Build confidence with a comfortable pace."},{"id":"balanced","label":"Balanced","description":"A steady mix of review and new practice."},{"id":"challenging","label":"Challenging","description":"I enjoy stretching my knowledge."}],"categories":[{"id":"all","title":"All words","description":"The complete beginner vocabulary.","symbol":"全"},{"id":"people","title":"People and family","description":"Pronouns, family members and jobs.","symbol":"人","words":["爸爸","儿子","工作","家","老师","妈妈","名字","女儿","你","朋友","人","谁","他","她","同学","我","我们","先生","学生","医生","小姐"]},{"id":"food","title":"Food and drinks","description":"Order tea or something to eat.","symbol":"茶","words":["菜","茶","吃","喝","米饭","苹果","水","水果"]},{"id":"numbers","title":"Numbers and quantities","description":"Counting, prices and amounts.","symbol":"三","words":["八","本","多","多少","二","个","几","九","块","六","钱","七","三","少","十","四","五","些","一","一点儿"]},{"id":"time","title":"Time and weather","description":"Days, hours and everyday weather.","symbol":"日","words":["点","分钟","号","今天","冷","明天","年","热","上午","时候","岁","天气","下雨","下午","现在","星期","月","中午","昨天"]},{"id":"places","title":"Places and travel","description":"School, cities and transport.","symbol":"国","words":["北京","出租车","饭店","飞机","回","来","哪儿","去","商店","上","下","学校","医院","在","中国","住","后面","前面","里"]},{"id":"actions","title":"Activities","description":"Reading, learning and everyday activities.","symbol":"学","words":["爱","打电话","读","会","叫","开","看","看见","买","能","请","认识","睡觉","说","听","喜欢","想","写","学习","有","坐","做"]},{"id":"objects","title":"Things and animals","description":"Objects and animals around you.","symbol":"书","words":["杯子","电脑","电视","电影","东西","狗","猫","书","衣服","椅子","桌子","字"]},{"id":"other","title":"Phrases and grammar","description":"Greetings, questions and connecting words.","symbol":"好"}],"courseLines":[{"id":"sounds","title":"Sounds & tones","color":"#326b9b","symbol":"声"},{"id":"everyday","title":"Everyday Chinese","color":"#377d62","symbol":"日"},{"id":"sentences","title":"Sentence building","color":"#826295","symbol":"句"}],"sources":[{"id":"hearmandarin","name":"HearMandarin","url":"https://hearmandarin.com/datasets/","license":"CC BY 4.0","attribution":"HearMandarin (https://hearmandarin.com)"},{"id":"hanzi-original","name":"Hanzi platform content","url":"https://hanzi-demo.netlify.app/","license":"Original educational content","attribution":"Hanzi project"}],"vocabularySelection":{"hsk2Levels":[1],"levelMapping":{"1":"beginner","2":"elementary","3":"intermediate","4":"intermediate","5":"advanced","6":"advanced"}}},"activities":[{"id":"lesson-tones","kind":"lesson","title":"Meet the tones","description":"Learn what tone marks mean before building your first phrases.","minutes":6,"category":"all","line":"sounds","position":{"x":110,"y":210},"prerequisites":[],"objectives":["Recognize the four written tone marks.","Notice that tones change in connected speech."],"explanation":["In Mandarin, pitch patterns help distinguish words. Pinyin marks the four tones: mā (high and level), má (rising), mǎ (low, with a possible rise), and mà (falling). These are a guide to pitch, not four different volume levels.","A third tone is often low without a full dip and rise inside a phrase. When two third tones meet, the first is usually pronounced like a second tone: 你好 is written nǐ hǎo but commonly spoken ní hǎo.","A neutral-tone syllable is short and unstressed; its pitch depends on the preceding tone. These questions check tone concepts. They do not measure your spoken pronunciation or acoustic tone accuracy."],"examples":[{"hanzi":"妈","pinyin":"mā","meaning":"Mum — first tone: high and level."},{"hanzi":"茶","pinyin":"chá","meaning":"Tea — second tone: rising."},{"hanzi":"水","pinyin":"shuǐ","meaning":"Water — third tone; its shape depends on context."},{"hanzi":"是","pinyin":"shì","meaning":"Be — fourth tone: falling."},{"hanzi":"妈妈","pinyin":"māma","meaning":"Mum — the second syllable is neutral in this common pronunciation."}],"questions":[{"id":"tones-level","type":"choice","prompt":"Written-tone check: which tone is high and level?","options":[{"id":"second","text":"Second tone: á"},{"id":"first","text":"First tone: ā"},{"id":"fourth","text":"Fourth tone: à"}],"answer":"first","explanation":"The first tone is high and level. The mark ā is a reminder of a level pitch.","hint":"Look for the horizontal tone mark."},{"id":"tones-rising","type":"choice","prompt":"Written-tone check: the mark in chá represents which pattern?","options":[{"id":"falling","text":"Falling"},{"id":"level","text":"High and level"},{"id":"rising","text":"Rising"}],"answer":"rising","explanation":"The acute mark á represents the second, rising tone.","hint":"The mark slopes upward."},{"id":"tones-falling","type":"choice","prompt":"Written-tone check: which syllable has a fourth tone?","options":[{"id":"shi","text":"shì"},{"id":"cha","text":"chá"},{"id":"shui","text":"shuǐ"}],"answer":"shi","explanation":"The mark ì slopes downward and denotes the fourth tone.","hint":"Find the downward-sloping mark."},{"id":"tones-sandhi","type":"choice","prompt":"In ordinary speech, how is the first tone of nǐ hǎo usually pronounced?","options":[{"id":"neutral","text":"As a neutral tone"},{"id":"rising","text":"Like a second tone"},{"id":"falling","text":"Like a fourth tone"}],"answer":"rising","explanation":"Before another third tone, the first third tone normally changes to a rising second tone. Dictionary pinyin still writes nǐ hǎo.","hint":"This phrase places two third tones together.","audioText":"你好"},{"id":"tones-neutral","type":"choice","prompt":"Which description fits a neutral-tone syllable?","options":[{"id":"level","text":"Always long and high"},{"id":"falling","text":"Always a fourth tone"},{"id":"short","text":"Short and unstressed; pitch depends on context"}],"answer":"short","explanation":"Neutral tone is not a fixed fifth pitch contour. It is unstressed and changes with context.","hint":"Think of the second syllable in māma.","audioText":"妈妈"}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"gentle","grammarTopicIds":["mandarin-tones"],"vocabularyIds":["hearmandarin:w00114","hearmandarin:w00146","hao","hearmandarin:w00017","shui"],"features":["tone-guide"]},{"id":"lesson-greetings","kind":"lesson","title":"First connections","description":"Say hello, thank someone, and turn a statement into a question.","minutes":6,"category":"other","line":"everyday","position":{"x":300,"y":210},"prerequisites":["lesson-tones"],"objectives":["Understand common greetings.","Use 吗 at the end of a yes-or-no question."],"explanation":["你好 (nǐ hǎo) is a useful beginner greeting. 谢谢 (xièxie) means “thank you”, and 不客气 (bú kèqi) is a common reply meaning “you are welcome”. Use 再见 (zàijiàn) to say goodbye.","Add 吗 (ma) at the end of a statement to make a yes-or-no question. 你好吗？ asks “How are you?” literally “Are you well?”; it is a useful learning example, not the only natural way to greet someone.","Pinyin below usually shows dictionary tones. Some examples show the spoken form: 不 is normally pronounced bú before a fourth tone, as in 不客气. Do not judge every syllable in isolation."],"examples":[{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Hello."},{"hanzi":"谢谢","pinyin":"xièxie","meaning":"Thank you."},{"hanzi":"不客气","pinyin":"bú kèqi","meaning":"You are welcome. (Spoken tone change on 不.)"},{"hanzi":"你好吗？","pinyin":"Nǐ hǎo ma?","meaning":"How are you? / Are you well?"}],"questions":[{"id":"greetings-listen","type":"choice","prompt":"Play the example and choose its meaning.","options":[{"id":"thanks","text":"Thank you"},{"id":"hello","text":"Hello"},{"id":"bye","text":"Goodbye"}],"answer":"hello","explanation":"你好 is the greeting “hello”. Its first syllable changes tone before the second third tone.","audioText":"你好","hint":"The two characters literally relate to “you” and “good”."},{"id":"greetings-reply","type":"choice","prompt":"Someone says 谢谢. Which reply means “you are welcome”?","options":[{"id":"bye","text":"再见","pinyin":"zàijiàn"},{"id":"hello","text":"你好","pinyin":"nǐ hǎo"},{"id":"welcome","text":"不客气","pinyin":"bú kèqi"}],"answer":"welcome","explanation":"不客气 is a common reply to 谢谢.","hint":"Choose the expression that tells someone there is no need to be polite."},{"id":"greetings-question","type":"order","prompt":"Build: “Are you well?”","tokens":["你","好","吗"],"acceptedOrders":[["你","好","吗"]],"explanation":"The statement 你好 becomes a yes-or-no question when 吗 is added at the end.","hint":"Put the question particle last.","audioText":"你好吗"},{"id":"greetings-ma","type":"choice","prompt":"Where does 吗 go in this kind of yes-or-no question?","options":[{"id":"end","text":"At the end"},{"id":"start","text":"Before the subject"},{"id":"middle","text":"Between the subject and verb"}],"answer":"end","explanation":"吗 follows the whole statement. The original word order stays the same.","hint":"Think of 你好吗？"},{"id":"greetings-goodbye","type":"choice","prompt":"Choose the expression for “goodbye”.","options":[{"id":"thanks","text":"谢谢","pinyin":"xièxie"},{"id":"bye","text":"再见","pinyin":"zàijiàn"},{"id":"welcome","text":"不客气","pinyin":"bú kèqi"}],"answer":"bye","explanation":"再见 means “goodbye”, literally suggesting seeing someone again.","hint":"It is the expression used when leaving."}],"fact":{"title":"A very old writing tradition","text":"Shang rulers recorded questions and outcomes on animal bones and tortoiseshells. These oracle-bone inscriptions preserve early Chinese written records, including questions about rain and hunting.","sourceUrl":"https://asia.si.edu/education/educator-resources/teaching-china-with-the-smithsonian/lesson-plans/making-sense-of-the-future-the-oracle-bone-and-shang-dynasty-divination/","sourceLabel":"Smithsonian National Museum of Asian Art"},"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["yes-no-ma","mandarin-tones"],"vocabularyIds":["hearmandarin:w00146","hao","hearmandarin:w00241","hearmandarin:w00014","hearmandarin:w00272","hearmandarin:w00115"],"features":[]},{"id":"lesson-introductions","kind":"lesson","title":"This is me","description":"Introduce yourself and build your first complete statements.","minutes":8,"category":"people","line":"sentences","position":{"x":490,"y":210},"prerequisites":["lesson-greetings"],"objectives":["Introduce your name and identity.","Place a time expression before the action."],"explanation":["我 means “I” and 你 means “you”. Use 叫 for a name: 我叫安娜 means “My name is Anna”. Use 是 before a noun describing an identity: 我是学生 means “I am a student”.","你叫什么名字？ asks “What is your name?” Here 什么 already asks “what”, so do not add 吗. 安娜 is an example name, not a required translation of your own name.","A basic action sentence follows subject → verb → object: 我学习汉语. A time expression such as 今天 goes before the verb, either before or after the subject: 今天我学习汉语 / 我今天学习汉语."],"examples":[{"hanzi":"我叫安娜。","pinyin":"Wǒ jiào Ānnà.","meaning":"My name is Anna."},{"hanzi":"我是学生。","pinyin":"Wǒ shì xuésheng.","meaning":"I am a student."},{"hanzi":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","meaning":"What is your name?"},{"hanzi":"我今天学习汉语。","pinyin":"Wǒ jīntiān xuéxí Hànyǔ.","meaning":"I study Chinese today."}],"questions":[{"id":"intro-listen","type":"choice","prompt":"Play the sentence and choose what the speaker tells you.","options":[{"id":"name","text":"Their name is Anna"},{"id":"job","text":"They are a teacher"},{"id":"drink","text":"They drink tea"}],"answer":"name","explanation":"我叫安娜 introduces the speaker’s name: Anna.","audioText":"我叫安娜","hint":"叫 introduces a name."},{"id":"intro-student","type":"order","prompt":"Build: “I am a student.”","tokens":["我","是","学生"],"acceptedOrders":[["我","是","学生"]],"explanation":"是 links the subject 我 to the noun 学生.","hint":"Person → 是 → identity.","audioText":"我是学生"},{"id":"intro-name-verb","type":"choice","prompt":"Which word introduces your name in 我___安娜？","options":[{"id":"study","text":"学习","pinyin":"xuéxí"},{"id":"called","text":"叫","pinyin":"jiào"},{"id":"at","text":"在","pinyin":"zài"}],"answer":"called","explanation":"叫 introduces what a person is called. 是 is used for identity, not in this name pattern.","hint":"Use the verb meaning “be called”."},{"id":"intro-today","type":"order","prompt":"Build: “I study Chinese today.”","tokens":["我","今天","学习","汉语"],"acceptedOrders":[["我","今天","学习","汉语"],["今天","我","学习","汉语"]],"explanation":"今天 goes before 学习. It can appear before or after 我, so both time placements are accepted.","hint":"Keep 今天 before the action."},{"id":"intro-wh-question","type":"choice","prompt":"Why does 你叫什么名字？ not need 吗?","options":[{"id":"short","text":"The sentence is too short"},{"id":"teacher","text":"Only teachers use 吗"},{"id":"what","text":"什么 already asks “what”"}],"answer":"what","explanation":"吗 creates a yes-or-no question; 什么 already asks for the missing information.","hint":"What kind of answer does “what is your name?” request?"}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["names-jiao","identity-shi","subject-verb-object","time-before-verb"],"vocabularyIds":["wo","hearmandarin:w00146","hearmandarin:w00091","hearmandarin:w00130","hearmandarin:w00188","hearmandarin:w00248","hearmandarin:w00107","hearmandarin:w00249","hearmandarin:w00069","hearmandarin:w00094"],"features":[]},{"id":"lesson-family","kind":"lesson","title":"People around me","description":"Talk about family, possession, and things people like.","minutes":8,"category":"people","line":"everyday","position":{"x":680,"y":110},"prerequisites":["lesson-introductions"],"objectives":["Use 的 for a possessive phrase.","Say who someone is and what they like."],"explanation":["爸爸 means “dad” and 妈妈 means “mum”. 我的妈妈 means “my mum”: the owner comes first, then 的, then the person or thing. With close family, 的 is also often omitted, as in 我妈妈.","他 and 她 are written differently but both are pronounced tā. 是 introduces an identity, while 有 means “have”. When counting people, 一个 is a basic number-classifier combination.","喜欢 means “like”. Put 也, meaning “also”, before the verb: 妈妈也喜欢茶. A neutral second syllable in bàba or māma should not be treated as a full fourth or first tone."],"examples":[{"hanzi":"我的妈妈","pinyin":"wǒ de māma","meaning":"My mum."},{"hanzi":"她是老师。","pinyin":"Tā shì lǎoshī.","meaning":"She is a teacher."},{"hanzi":"我有一个女儿。","pinyin":"Wǒ yǒu yí ge nǚ’ér.","meaning":"I have one daughter. (A common spoken form of 一个.)"},{"hanzi":"妈妈也喜欢茶。","pinyin":"Māma yě xǐhuan chá.","meaning":"Mum likes tea too."}],"questions":[{"id":"family-listen","type":"choice","prompt":"Play the phrase and choose the family member.","options":[{"id":"teacher","text":"Teacher"},{"id":"mum","text":"Mum"},{"id":"dad","text":"Dad"}],"answer":"mum","explanation":"妈妈 is mum. Its second syllable is commonly neutral.","audioText":"妈妈","hint":"Listen for māma."},{"id":"family-mine","type":"order","prompt":"Build the full possessive phrase: “my mum”. Use every tile.","tokens":["我","的","妈妈"],"acceptedOrders":[["我","的","妈妈"]],"explanation":"In the full possessive form, the owner 我 comes before 的 and 妈妈. 我妈妈 is also natural, but this exercise supplies 的.","hint":"Owner → 的 → person."},{"id":"family-teacher","type":"order","prompt":"Build: “She is a teacher.”","tokens":["她","是","老师"],"acceptedOrders":[["她","是","老师"]],"explanation":"她 is the subject, 是 links the identity, and 老师 is teacher.","hint":"Person → 是 → identity."},{"id":"family-also","type":"choice","prompt":"Where does 也 go in “Mum also likes tea”?","options":[{"id":"end","text":"After 茶"},{"id":"first","text":"Before 妈妈"},{"id":"before-verb","text":"Before 喜欢"}],"answer":"before-verb","explanation":"The pattern is 妈妈也喜欢茶: 也 comes before the verb 喜欢.","hint":"也 modifies the following action."},{"id":"family-two-likes","type":"order","prompt":"Build: “I like tea, and Dad likes tea too.”","tokens":["我","喜欢","茶","，","爸爸","也","喜欢","茶"],"acceptedOrders":[["我","喜欢","茶","，","爸爸","也","喜欢","茶"]],"explanation":"Each clause has a subject and 喜欢茶. The second clause adds 也 before 喜欢. Identical 茶 and 喜欢 tiles are interchangeable.","hint":"Finish 我喜欢茶 first, then add the clause about Dad."}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["possession-de","identity-shi","also-ye","classifiers"],"vocabularyIds":["hearmandarin:w00003","hearmandarin:w00114","wo","hearmandarin:w00202","hearmandarin:w00200","hearmandarin:w00030","hearmandarin:w00263","hearmandarin:w00153","hearmandarin:w00060","hearmandarin:w00107","hearmandarin:w00225","hearmandarin:w00017"],"features":[]},{"id":"lesson-food","kind":"lesson","title":"Tea, please","description":"Ask for a drink and describe what you do or do not drink.","minutes":8,"category":"food","line":"everyday","position":{"x":680,"y":310},"prerequisites":["lesson-introductions"],"objectives":["Build subject–verb–object sentences.","Use 想 and 不 before the action.","Recognize a quantity phrase for a drink."],"explanation":["喝 means “drink”. Start with the subject, then the verb, then the drink: 我喝水. 想 before the verb expresses wanting to do something: 我想喝茶 means “I would like to drink tea”.","不 goes before the verb to negate a habitual action or present intention: 我不喝茶 means “I do not drink tea”. Here 不 is bù because 喝 has a first tone; before a fourth tone it normally changes to bú.","For a drink, 一杯水 means “one cup of water”: number → container measure → drink. 杯子 is the noun “cup”; 杯 is the measure used in this phrase. 一 has dictionary tone yī but is pronounced yì before the first tone of 杯."],"examples":[{"hanzi":"我喝水。","pinyin":"Wǒ hē shuǐ.","meaning":"I drink water."},{"hanzi":"我想喝茶。","pinyin":"Wǒ xiǎng hē chá.","meaning":"I would like to drink tea."},{"hanzi":"我不喝茶。","pinyin":"Wǒ bù hē chá.","meaning":"I do not drink tea."},{"hanzi":"一杯水，谢谢。","pinyin":"Yì bēi shuǐ, xièxie.","meaning":"One cup of water, thank you."}],"questions":[{"id":"food-listen","type":"choice","prompt":"Play the sentence. What does the speaker want to drink?","options":[{"id":"water","text":"Water"},{"id":"rice","text":"Rice"},{"id":"tea","text":"Tea"}],"answer":"tea","explanation":"我想喝茶 ends in 茶: the speaker wants tea.","audioText":"我想喝茶","hint":"茶 is chá."},{"id":"food-drink","type":"order","prompt":"Build: “I drink water.”","tokens":["我","喝","水"],"acceptedOrders":[["我","喝","水"]],"explanation":"The subject 我 comes before 喝, and the object 水 follows it.","hint":"Who → action → drink."},{"id":"food-want","type":"order","prompt":"Build: “I would like to drink tea.”","tokens":["我","想","喝","茶"],"acceptedOrders":[["我","想","喝","茶"]],"explanation":"想 goes before the action 喝: wanting to drink tea.","hint":"Place 想 immediately before 喝."},{"id":"food-negative","type":"choice","prompt":"What does 我不喝茶 mean?","options":[{"id":"no-tea","text":"I do not drink tea"},{"id":"want-tea","text":"I want tea"},{"id":"no-water","text":"I do not drink water"}],"answer":"no-tea","explanation":"不 negates 喝, while 茶 remains the object.","hint":"不 is the negative word."},{"id":"food-cup","type":"order","prompt":"Build: “one cup of water”.","tokens":["一","杯","水"],"acceptedOrders":[["一","杯","水"]],"explanation":"Put the number first, then 杯 as the container measure, then the drink 水.","hint":"Number → cup measure → drink."}],"fact":{"title":"Tea is also a social practice","text":"In 2022, UNESCO listed China’s traditional tea processing and associated social practices as intangible cultural heritage. The entry includes drinking and sharing tea, not only producing it.","sourceUrl":"https://ich.unesco.org/en/RL/traditional-tea-processing-techniques-and-associated-social-practices-in-china-01884","sourceLabel":"UNESCO Intangible Cultural Heritage"},"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["subject-verb-object","want-xiang","negation-bu","classifiers"],"vocabularyIds":["hearmandarin:w00017","shui","hearmandarin:w00077","hearmandarin:w00233","wo","hearmandarin:w00013","hearmandarin:w00009","hearmandarin:w00254","hearmandarin:w00241","hearmandarin:w00225"],"features":[]},{"id":"lesson-checkpoint","kind":"lesson","title":"First journey checkpoint","description":"Bring greetings, family, drinks, and sentence patterns together.","minutes":8,"category":"all","line":"sentences","position":{"x":880,"y":210},"prerequisites":["lesson-family","lesson-food"],"objectives":["Choose expressions that fit a short encounter.","Recall tone changes and basic sentence patterns without hints."],"explanation":["This stop reviews the first unit. Aim to answer at least 80% independently; hints remain available for learning but assisted answers do not raise the independent score.","Listen to an example when the speaker button is available. This review checks understanding and sentence construction. It does not certify spoken tone accuracy; use the linked speaking practice to rehearse and compare recordings."],"examples":[{"hanzi":"你好，我是学生。","pinyin":"Nǐ hǎo, wǒ shì xuésheng.","meaning":"Hello, I am a student."},{"hanzi":"妈妈喜欢茶。","pinyin":"Māma xǐhuan chá.","meaning":"Mum likes tea."}],"questions":[{"id":"checkpoint-listen","type":"choice","prompt":"Play the sentence and choose the correct meaning.","options":[{"id":"dad","text":"Dad likes water"},{"id":"mum","text":"Mum likes tea"},{"id":"student","text":"I am a student"}],"answer":"mum","explanation":"妈妈 is mum; 喜欢 is like; 茶 is tea.","audioText":"妈妈喜欢茶","hint":"Identify the subject and the drink separately."},{"id":"checkpoint-identity","type":"order","prompt":"Build: “I am a student.”","tokens":["我","是","学生"],"acceptedOrders":[["我","是","学生"]],"explanation":"Identity uses subject → 是 → noun.","hint":"是 connects a person to an identity."},{"id":"checkpoint-tones","type":"choice","prompt":"Which statement about spoken 你好 is correct?","options":[{"id":"always","text":"Both syllables must always have a full dip and rise"},{"id":"neutral","text":"The first syllable is always neutral"},{"id":"change","text":"The first third tone usually becomes rising before the next third tone"}],"answer":"change","explanation":"Third-tone sandhi changes the first tone to a rising tone in this two-syllable phrase.","hint":"Recall what happens when two third tones meet."},{"id":"checkpoint-drink","type":"order","prompt":"Build: “I would like to drink water.”","tokens":["我","想","喝","水"],"acceptedOrders":[["我","想","喝","水"]],"explanation":"想 precedes 喝, and 水 follows the action as its object.","hint":"Who → would like → drink → what."},{"id":"checkpoint-today","type":"order","prompt":"Build: “I study Chinese today.”","tokens":["我","今天","学习","汉语"],"acceptedOrders":[["我","今天","学习","汉语"],["今天","我","学习","汉语"]],"explanation":"The time expression 今天 goes before 学习, either before or after 我.","hint":"Time belongs before the action."}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["mandarin-tones","identity-shi","want-xiang","time-before-verb"],"vocabularyIds":["hearmandarin:w00146","hao","wo","hearmandarin:w00188","hearmandarin:w00248","hearmandarin:w00114","hearmandarin:w00225","hearmandarin:w00017","hearmandarin:w00233","hearmandarin:w00077","shui","hearmandarin:w00094","hearmandarin:w00249","hearmandarin:w00069"],"features":[]},{"id":"exercise-introductions","kind":"exercise","title":"Meet a new classmate","description":"Listen, choose a reply, and introduce yourself in a short encounter.","minutes":7,"category":"people","line":"sentences","position":{"x":0,"y":0},"prerequisites":[],"objectives":["Understand a simple introduction.","Choose a suitable response.","Construct statements and questions."],"explanation":["You meet Anna before a Chinese class. Complete the five tasks in the conversation. Everything needed is shown in the examples, and you can enter this exercise without completing the course.","Use 叫 for names, 是 for identities, and 吗 for a yes-or-no question. The answers in this activity check comprehension and sentence order, not your spoken pronunciation."],"examples":[{"hanzi":"你好，我叫安娜。","pinyin":"Nǐ hǎo, wǒ jiào Ānnà.","meaning":"Hello, my name is Anna."},{"hanzi":"你是学生吗？","pinyin":"Nǐ shì xuésheng ma?","meaning":"Are you a student?"}],"questions":[{"id":"meet-listen","type":"choice","prompt":"Listen to Anna. What does she tell you?","options":[{"id":"teacher","text":"She is a teacher"},{"id":"name","text":"Her name is Anna"},{"id":"drink","text":"She wants water"}],"answer":"name","explanation":"叫 introduces a name; 安娜 is Anna.","audioText":"你好，我叫安娜","hint":"Focus on the words after 叫."},{"id":"meet-reply","type":"choice","prompt":"You want to greet Anna back. Which expression fits?","options":[{"id":"bye","text":"再见","pinyin":"zàijiàn"},{"id":"hello","text":"你好","pinyin":"nǐ hǎo"},{"id":"water","text":"水","pinyin":"shuǐ"}],"answer":"hello","explanation":"你好 is the greeting. 再见 would end the encounter.","hint":"Choose the greeting, not the farewell."},{"id":"meet-name","type":"order","prompt":"Build: “My name is Anna.”","tokens":["我","叫","安娜"],"acceptedOrders":[["我","叫","安娜"]],"explanation":"The pattern 我叫 + name introduces the speaker.","hint":"Person → be called → name."},{"id":"meet-student","type":"order","prompt":"Build: “I am a student.”","tokens":["我","是","学生"],"acceptedOrders":[["我","是","学生"]],"explanation":"是 connects 我 to the identity 学生.","hint":"Use the identity verb between the person and noun."},{"id":"meet-question","type":"order","prompt":"Ask: “Are you a teacher?”","tokens":["你","是","老师","吗"],"acceptedOrders":[["你","是","老师","吗"]],"explanation":"Start with 你是老师, then add 吗 to make a yes-or-no question.","hint":"The question particle belongs last."}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["names-jiao","identity-shi","yes-no-ma"],"vocabularyIds":["hearmandarin:w00146","hao","wo","hearmandarin:w00091","hearmandarin:w00188","hearmandarin:w00248","hearmandarin:w00107","hearmandarin:w00130","hearmandarin:w00115"],"features":[]},{"id":"exercise-family","kind":"exercise","title":"A family portrait","description":"Understand who someone is and describe the people around them.","minutes":8,"category":"people","line":"everyday","position":{"x":0,"y":0},"prerequisites":[],"objectives":["Understand a family description.","Use possession and identity.","Connect two preferences using 也."],"explanation":["Imagine showing a family photo to a friend. Identify the person, explain their job, and compare what people like. Listen where an audio example is provided, then build your own sentences.","我的妈妈 is the full possessive form of “my mum”; 我妈妈 is also common. 也 goes before the verb, not at the end of the sentence."],"examples":[{"hanzi":"我的妈妈是老师。","pinyin":"Wǒ de māma shì lǎoshī.","meaning":"My mum is a teacher."},{"hanzi":"爸爸也喜欢茶。","pinyin":"Bàba yě xǐhuan chá.","meaning":"Dad likes tea too."}],"questions":[{"id":"portrait-listen","type":"choice","prompt":"Listen. What is the speaker’s mum’s job?","options":[{"id":"doctor","text":"Doctor"},{"id":"student","text":"Student"},{"id":"teacher","text":"Teacher"}],"answer":"teacher","explanation":"老师 is teacher. The sentence says 我的妈妈是老师.","audioText":"我的妈妈是老师","hint":"The job follows 是."},{"id":"portrait-mum","type":"order","prompt":"Build the full phrase “my mum” using every tile.","tokens":["我","的","妈妈"],"acceptedOrders":[["我","的","妈妈"]],"explanation":"The full possessive form puts 的 between the owner and the person.","hint":"Owner first; person last."},{"id":"portrait-job","type":"order","prompt":"Build: “She is a teacher.”","tokens":["她","是","老师"],"acceptedOrders":[["她","是","老师"]],"explanation":"The identity pattern is subject → 是 → job.","hint":"Use 是 to connect the two nouns."},{"id":"portrait-also","type":"choice","prompt":"爸爸也喜欢茶 tells you that…","options":[{"id":"also","text":"Dad likes tea too"},{"id":"not","text":"Dad does not like tea"},{"id":"mum","text":"Mum drinks water"}],"answer":"also","explanation":"也 means “also” and 喜欢茶 means “like tea”.","hint":"Look at what 也 adds to the meaning."},{"id":"portrait-compare","type":"order","prompt":"Build: “I like tea, and Dad likes tea too.”","tokens":["我","喜欢","茶","，","爸爸","也","喜欢","茶"],"acceptedOrders":[["我","喜欢","茶","，","爸爸","也","喜欢","茶"]],"explanation":"Build the first statement, then put 也 before 喜欢 in the second. Identical word tiles can exchange places.","hint":"Keep the comma between the two clauses."}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["possession-de","identity-shi","also-ye"],"vocabularyIds":["hearmandarin:w00003","hearmandarin:w00114","wo","hearmandarin:w00202","hearmandarin:w00030","hearmandarin:w00188","hearmandarin:w00107","hearmandarin:w00225","hearmandarin:w00017"],"features":[]},{"id":"exercise-cafe","kind":"exercise","title":"A stop at the café","description":"Choose a drink, order it, and finish the exchange politely.","minutes":7,"category":"food","line":"everyday","position":{"x":0,"y":0},"prerequisites":[],"objectives":["Understand a drink choice.","Express what you want and do not want.","Use a quantity phrase and a polite ending."],"explanation":["You stop for a drink with a friend. Understand their choice, say what you would like, and order a cup of water. This is a short guided scenario rather than an unrestricted conversation simulator.","想 precedes the action, 不 negates it, and a quantity phrase follows number → measure → drink. 一杯水，谢谢 is a concise order: “One cup of water, thank you.”"],"examples":[{"hanzi":"我想喝茶。","pinyin":"Wǒ xiǎng hē chá.","meaning":"I would like to drink tea."},{"hanzi":"我不喝茶。","pinyin":"Wǒ bù hē chá.","meaning":"I do not drink tea."},{"hanzi":"一杯水，谢谢。","pinyin":"Yì bēi shuǐ, xièxie.","meaning":"One cup of water, thank you."}],"questions":[{"id":"cafe-listen","type":"choice","prompt":"Listen to your friend. Which drink do they want?","options":[{"id":"tea","text":"Tea"},{"id":"water","text":"Water"},{"id":"rice","text":"Rice"}],"answer":"tea","explanation":"茶 is the final word in 我想喝茶: your friend wants tea.","audioText":"我想喝茶","hint":"Listen for chá."},{"id":"cafe-water","type":"order","prompt":"Build: “I would like to drink water.”","tokens":["我","想","喝","水"],"acceptedOrders":[["我","想","喝","水"]],"explanation":"想 precedes 喝 and 水 is the object of the action.","hint":"Who → want → drink → what."},{"id":"cafe-no-tea","type":"order","prompt":"Build: “I do not drink tea.”","tokens":["我","不","喝","茶"],"acceptedOrders":[["我","不","喝","茶"]],"explanation":"Place 不 directly before 喝 to negate the action.","hint":"The negative word goes before the verb."},{"id":"cafe-cup","type":"order","prompt":"Build: “One cup of water, thank you.”","tokens":["一","杯","水","，","谢谢"],"acceptedOrders":[["一","杯","水","，","谢谢"]],"explanation":"一杯水 is the quantity phrase; 谢谢 adds a polite ending.","hint":"Finish the order before the comma."},{"id":"cafe-reply","type":"choice","prompt":"The server says 不客气 after your 谢谢. What does it mean?","options":[{"id":"bye","text":"Goodbye"},{"id":"welcome","text":"You are welcome"},{"id":"no-tea","text":"There is no tea"}],"answer":"welcome","explanation":"不客气 is a common reply to thanks.","hint":"Recall the exchange from the greetings stop."}],"source":"platform","revision":1,"publication":"published","languageLevel":"beginner","difficulty":"balanced","grammarTopicIds":["want-xiang","negation-bu","classifiers"],"vocabularyIds":["hearmandarin:w00017","shui","wo","hearmandarin:w00233","hearmandarin:w00077","hearmandarin:w00013","hearmandarin:w00254","hearmandarin:w00009","hearmandarin:w00241","hearmandarin:w00014"],"features":[]}],"grammarTopics":[{"id":"subject-verb-object","languageLevel":"beginner","difficulty":"balanced","title":"Subject → verb → object","explanation":"A basic statement names the person doing the action first, followed by the action and its object.","examples":[{"hanzi":"我喝水。","pinyin":"Wǒ hē shuǐ.","meaning":"I drink water."}],"prerequisites":[]},{"id":"identity-shi","languageLevel":"beginner","difficulty":"balanced","title":"Identity with 是","explanation":"是 connects the subject to a noun describing their identity or category. Here, it says that I am a student.","examples":[{"hanzi":"我是学生。","pinyin":"Wǒ shì xuésheng.","meaning":"I am a student."}],"prerequisites":[]},{"id":"yes-no-ma","languageLevel":"beginner","difficulty":"balanced","title":"Questions with 吗","explanation":"Adding 吗 to the end of a statement turns it into a yes-or-no question. The basic word order stays the same.","examples":[{"hanzi":"你是老师吗？","pinyin":"Nǐ shì lǎoshī ma?","meaning":"Are you a teacher?"}],"prerequisites":[]},{"id":"negation-bu","languageLevel":"beginner","difficulty":"balanced","title":"Negation before the verb","explanation":"For this habitual action, 不 goes directly before the verb 喝. It changes “drink” into “do not drink”.","examples":[{"hanzi":"我不喝茶。","pinyin":"Wǒ bù hē chá.","meaning":"I do not drink tea."}],"prerequisites":[]},{"id":"location-zai","languageLevel":"beginner","difficulty":"balanced","title":"Location with 在","explanation":"Here, 在 describes where someone is. Use 在 followed by the name of the place.","examples":[{"hanzi":"他在学校。","pinyin":"Tā zài xuéxiào.","meaning":"He is at school."}],"prerequisites":[]},{"id":"time-before-verb","languageLevel":"beginner","difficulty":"balanced","title":"Time before the verb","explanation":"今天 gives the time and goes before the action 学习. 今天我学习汉语 is also accepted: the time expression can go before or after the subject.","examples":[{"hanzi":"我今天学习汉语。","pinyin":"Wǒ jīntiān xuéxí Hànyǔ.","meaning":"I study Chinese today."}],"prerequisites":[]},{"id":"preference-xihuan","languageLevel":"beginner","difficulty":"balanced","title":"The object after 喜欢","explanation":"喜欢 means to like something. The thing you like follows the verb; 中国菜 is a single phrase here.","examples":[{"hanzi":"我喜欢中国菜。","pinyin":"Wǒ xǐhuan Zhōngguó cài.","meaning":"I like Chinese food."}],"prerequisites":[]},{"id":"classifiers","languageLevel":"beginner","difficulty":"balanced","title":"Number → classifier → noun","explanation":"When counting books, put the classifier 本 between the number 三 and the noun 书. 三本书 means three books.","examples":[{"hanzi":"她有三本书。","pinyin":"Tā yǒu sān běn shū.","meaning":"She has three books."}],"prerequisites":[]},{"id":"time-destination","languageLevel":"beginner","difficulty":"balanced","title":"Time and destination","explanation":"明天 places the action tomorrow. 北京 follows 去 as the destination. 明天我们去北京 is also accepted.","examples":[{"hanzi":"我们明天去北京。","pinyin":"Wǒmen míngtiān qù Běijīng.","meaning":"We are going to Beijing tomorrow."}],"prerequisites":[]},{"id":"also-ye","languageLevel":"beginner","difficulty":"balanced","title":"也 before the verb","explanation":"也 means “also” and goes before the verb 喜欢. The comma separates two simple clauses. The two 茶 tiles and the two 喜欢 tiles are interchangeable.","examples":[{"hanzi":"我喜欢茶，爸爸也喜欢茶。","pinyin":"Wǒ xǐhuan chá, bàba yě xǐhuan chá.","meaning":"I like tea, and Dad likes tea too."}],"prerequisites":[]},{"id":"mandarin-tones","title":"Written tones and connected speech","explanation":"In Mandarin, pitch patterns help distinguish words. Pinyin marks the four tones: mā (high and level), má (rising), mǎ (low, with a possible rise), and mà (falling). These are a guide to pitch, not four different volume levels.\n\nA third tone is often low without a full dip and rise inside a phrase. When two third tones meet, the first is usually pronounced like a second tone: 你好 is written nǐ hǎo but commonly spoken ní hǎo.\n\nA neutral-tone syllable is short and unstressed; its pitch depends on the preceding tone. These questions check tone concepts. They do not measure your spoken pronunciation or acoustic tone accuracy.","examples":[{"hanzi":"妈","pinyin":"mā","meaning":"Mum — first tone: high and level."},{"hanzi":"茶","pinyin":"chá","meaning":"Tea — second tone: rising."},{"hanzi":"水","pinyin":"shuǐ","meaning":"Water — third tone; its shape depends on context."},{"hanzi":"是","pinyin":"shì","meaning":"Be — fourth tone: falling."},{"hanzi":"妈妈","pinyin":"māma","meaning":"Mum — the second syllable is neutral in this common pronunciation."}],"languageLevel":"beginner","difficulty":"balanced","prerequisites":[]},{"id":"names-jiao","title":"Introducing a name with 叫","explanation":"我 means “I” and 你 means “you”. Use 叫 for a name: 我叫安娜 means “My name is Anna”. Use 是 before a noun describing an identity: 我是学生 means “I am a student”.","examples":[{"hanzi":"我叫安娜。","pinyin":"Wǒ jiào Ānnà.","meaning":"My name is Anna."}],"languageLevel":"beginner","difficulty":"balanced","prerequisites":[]},{"id":"possession-de","title":"Possession with 的","explanation":"爸爸 means “dad” and 妈妈 means “mum”. 我的妈妈 means “my mum”: the owner comes first, then 的, then the person or thing. With close family, 的 is also often omitted, as in 我妈妈.","examples":[{"hanzi":"我的妈妈","pinyin":"wǒ de māma","meaning":"My mum."}],"languageLevel":"beginner","difficulty":"balanced","prerequisites":[]},{"id":"want-xiang","title":"Wanting to do something with 想","explanation":"喝 means “drink”. Start with the subject, then the verb, then the drink: 我喝水. 想 before the verb expresses wanting to do something: 我想喝茶 means “I would like to drink tea”.","examples":[{"hanzi":"我想喝茶。","pinyin":"Wǒ xiǎng hē chá.","meaning":"I would like to drink tea."}],"languageLevel":"beginner","difficulty":"balanced","prerequisites":[]}],"sentences":[{"id":"sentence-drink-water","meaning":"I drink water.","pinyin":"Wǒ hē shuǐ.","tokens":["我","喝","水"],"punctuation":"。","grammarParts":[{"label":"Who","text":"我 · I"},{"label":"Action","text":"喝 · drink"},{"label":"What","text":"水 · water"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"subject-verb-object"},{"id":"sentence-student","meaning":"I am a student.","pinyin":"Wǒ shì xuésheng.","tokens":["我","是","学生"],"punctuation":"。","grammarParts":[{"label":"Subject","text":"我 · I"},{"label":"Link","text":"是 · be"},{"label":"Identity","text":"学生 · student"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"identity-shi"},{"id":"sentence-teacher-question","meaning":"Are you a teacher?","pinyin":"Nǐ shì lǎoshī ma?","tokens":["你","是","老师","吗"],"punctuation":"？","grammarParts":[{"label":"Statement","text":"你是老师 · you are a teacher"},{"label":"Question","text":"吗 · question particle"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"yes-no-ma"},{"id":"sentence-no-tea","meaning":"I do not drink tea.","pinyin":"Wǒ bù hē chá.","tokens":["我","不","喝","茶"],"punctuation":"。","grammarParts":[{"label":"Subject","text":"我 · I"},{"label":"Negation + action","text":"不喝 · do not drink"},{"label":"Object","text":"茶 · tea"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"negation-bu"},{"id":"sentence-at-school","meaning":"He is at school.","pinyin":"Tā zài xuéxiào.","tokens":["他","在","学校"],"punctuation":"。","grammarParts":[{"label":"Who","text":"他 · he"},{"label":"Location verb","text":"在 · be at"},{"label":"Where","text":"学校 · school"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"location-zai"},{"id":"sentence-today-study","meaning":"I study Chinese today.","pinyin":"Wǒ jīntiān xuéxí Hànyǔ.","tokens":["我","今天","学习","汉语"],"punctuation":"。","acceptedOrders":[["今天","我","学习","汉语"]],"grammarParts":[{"label":"Subject","text":"我 · I"},{"label":"When","text":"今天 · today"},{"label":"Action","text":"学习 · study"},{"label":"What","text":"汉语 · Chinese"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"time-before-verb"},{"id":"sentence-chinese-food","meaning":"I like Chinese food.","pinyin":"Wǒ xǐhuan Zhōngguó cài.","tokens":["我","喜欢","中国菜"],"punctuation":"。","grammarParts":[{"label":"Who","text":"我 · I"},{"label":"Preference","text":"喜欢 · like"},{"label":"What","text":"中国菜 · Chinese food"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"preference-xihuan"},{"id":"sentence-three-books","meaning":"She has three books.","pinyin":"Tā yǒu sān běn shū.","tokens":["她","有","三","本","书"],"punctuation":"。","grammarParts":[{"label":"Subject + verb","text":"她有 · she has"},{"label":"Number","text":"三 · three"},{"label":"Classifier","text":"本 · for books"},{"label":"Noun","text":"书 · book"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"classifiers"},{"id":"sentence-tomorrow-beijing","meaning":"We are going to Beijing tomorrow.","pinyin":"Wǒmen míngtiān qù Běijīng.","tokens":["我们","明天","去","北京"],"punctuation":"。","acceptedOrders":[["明天","我们","去","北京"]],"grammarParts":[{"label":"Who","text":"我们 · we"},{"label":"When","text":"明天 · tomorrow"},{"label":"Action","text":"去 · go"},{"label":"Where to","text":"北京 · Beijing"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"time-destination"},{"id":"sentence-family-tea","meaning":"I like tea, and Dad likes tea too.","pinyin":"Wǒ xǐhuan chá, bàba yě xǐhuan chá.","tokens":["我","喜欢","茶","，","爸爸","也","喜欢","茶"],"punctuation":"。","grammarParts":[{"label":"First clause","text":"我喜欢茶 · I like tea"},{"label":"Second subject","text":"爸爸 · Dad"},{"label":"Also + action","text":"也喜欢 · also likes"},{"label":"Object","text":"茶 · tea"}],"languageLevel":"beginner","difficulty":"balanced","grammarTopicId":"also-ye"}],"vocabulary":[{"id":"hearmandarin:w00001","hanzi":"爱","pinyin":"ài","meaning":"to love","categoryId":"actions","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00001","traditional":"愛","partOfSpeech":"verb"},{"id":"hearmandarin:w00002","hanzi":"八","pinyin":"bā","meaning":"eight","categoryId":"numbers","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00002","traditional":"八","partOfSpeech":"numeral"},{"id":"hearmandarin:w00003","hanzi":"爸爸","pinyin":"bàba","meaning":"father; dad","categoryId":"people","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00003","traditional":"爸爸","partOfSpeech":"noun"},{"id":"hearmandarin:w00009","hanzi":"杯子","pinyin":"bēizi","meaning":"cup; glass","categoryId":"objects","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00009","traditional":"杯子","partOfSpeech":"noun"},{"id":"hearmandarin:w00010","hanzi":"本","pinyin":"běn","meaning":"measure word for books; root","categoryId":"numbers","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00010","traditional":"本","partOfSpeech":"measure word"},{"id":"hearmandarin:w00013","hanzi":"不","pinyin":"bù","meaning":"no; not","categoryId":"other","level":1,"languageLevel":"beginner","difficulty":"balanced","sourceId":"hearmandarin","sourceEntryId":"w00013","traditional":"不","partOfSpeech":"adverb"},{"id":"hearmandarin:w00014","hanzi":"不客气","pinyin":"bú kèqi","meaning":"you're welcome","categoryId":"other","level":1,"languageLevel":"beginner","difficulty":"bala